# RW2DM_ORIENT: Orient: two reference points to two target points with Copy and Scale options. The script is rw2dm_orient_script.txt; generated by rw2dm_gen.py (the closed forms are in that file). Every object kind of the case (Point, Line, Plane, Box) is
# compared with the closed-form image of the operation: points by the residual move to the origin (printed 0,0,0 within 1e-9), curve / surface control points
# through ExtractPt the same way, boxes by their bounding box after a residual move. RW2DM_ORIENT_sensitivity shows that a 1e-6 error would read 1e-06.
RW2_ORIENT_OUT=""
rw2_orient_run() {
  local o
  if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
    o="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/$1" 2>&1)" || { echo "$o" | tail -40; echo "FAIL RW2DM_ORIENT_run: $1 exited non-zero"; fail=1; o=""; }
  else
    o="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/$1" 2>&1)" || { echo "$o" | tail -40; echo "FAIL RW2DM_ORIENT_run: $1 exited non-zero"; fail=1; o=""; }
  fi
  RW2_ORIENT_OUT+="$o"$'\n'
}
rw2_orient_run rw2dm_orient_script.txt
rw2_orient_block() { awk -v name="$1" '$0 ~ ("Unknown command: RW2BEGIN_" name "$") { on = 1; next } on && /Unknown command: RW2BEGIN_/ { exit } on { print }' <<<"$RW2_ORIENT_OUT"; }
# rw2_orient_resid NAME NPTS BOXES DESC: the case listed exactly NPTS points, every one at residual 0,0,0, and the boxes' bounding boxes (joined by ';') read exactly BOXES
rw2_orient_resid() {
  local blk npts zeros boxes; blk="$(rw2_orient_block "$1")"
  npts="$({ grep -cE '^history: Object [0-9]+ \(point\)' <<<"$blk" || true; })"
  zeros="$({ grep -cE '^history:   0,0,0$' <<<"$blk" || true; })"
  boxes="$({ grep -E '^history: Bounding box min ' <<<"$blk" || true; } | sed -E 's/^history: Bounding box //' | paste -sd';' -)"
  if [ "$npts" = "$2" ] && [ "$zeros" = "$2" ] && [ "$boxes" = "$3" ]; then echo "ok   RW2DM_ORIENT_$1: $4 ($2 points at residual 0 within 1e-9; boxes: ${3:-none})"
  else echo "FAIL RW2DM_ORIENT_$1: $4 (listed $npts points, $zeros at residual 0, expected $2 and $2; boxes '$boxes', expected '$3')"; fail=1; { grep -E '^history:   |^history: Bounding box|^history: ! ' <<<"$blk" || true; } | head -16 | sed 's/^/     residual: /'; fi
}
rw2_orient_resid copyscale 14 "min 0,0,0 max 2,2,2;min 0,0,0 max 4,4,4" "Orient Copy=Yes: reference (0,0,0)-(2,0,0) to target (5,5,0)-(5,9,0): the originals stay and copies are turned 90 degrees and scaled by 4 / 2 about the first point"
rw2_orient_resid rigid 7 "min 0,0,0 max 2,2,2" "Orient Scale=No: reference (1,1,0)-(4,1,0) to target (0,0,0)-(0,6,0): a rigid map (90 degree turn about the first reference point, then onto the first target), no scaling although the lengths differ"
rw2_orient_resid default 7 "min 0,0,0 max 4,4,4" "Orient with the default options still scales by |target| / |reference| (3 to 6: factor 2) and moves the originals"
rw2_orient_resid half 7 "min 0,0,0 max 2,2,2" "Orient Scale=No with opposite directions in the plane: reference (0,0,0)-(1,0,0) to target (3,3,0)-(2,3,0) is a half turn plus a translation"
rw2_orient_resid tilt 14 "min 0,0,0 max 2,2,2;min 0,0,0 max 2,2,2" "Orient Scale=No Copy=Yes with a reference direction in the plane and a target direction out of it: (0,0,0)-(4,0,0) to (0,0,0)-(0,0,3) is the 90 degree turn of x onto z about x cross z"
rw2_orient_resid tiltscale 7 "min 0,0,0 max 4,4,4" "Orient (scale on) from (0,0,0)-(1,0,0) to (2,0,0)-(2,0,2): turn x onto z, scale by 2, move the first point to (2,0,0)"
# negative control: the same harness must SEE a 1e-6 error (a point 1e-6 off its expected image reads 1e-06, not 0)
rw2_orient_sens() {
  local blk; blk="$(rw2_orient_block sensitivity)"
  if grep -qE '^history:   (0,0,)?[-0-9.e]*1e-06' <<<"$blk" && ! grep -qE '^history:   0,0,0$' <<<"$blk"; then echo "ok   RW2DM_ORIENT_sensitivity: the residual harness reports a 1e-6 error as 1e-06 (negative control)"
  else echo "FAIL RW2DM_ORIENT_sensitivity: a 1e-6 error was not visible"; fail=1; { grep -E '^history:   ' <<<"$blk" || true; } | head -4 | sed 's/^/     residual: /'; fi
}
rw2_orient_sens
